public static GUPPricingSimulatorInstanceValue findOrCreate(ConfigName _name, DataAreaId _pricingSimulatorDataAreaId)
{
    GUPPricingSimulatorInstanceValue gupPricingSimulatorInstanceValue;

    if (_name && _pricingSimulatorDataAreaId)
    {
        gupPricingSimulatorInstanceValue = GUPPricingSimulatorInstanceValue::findByPricingSimulator(_name, _pricingSimulatorDataAreaId, false);

        // Insert new value if no record identifier found.
        if (!gupPricingSimulatorInstanceValue.RecId)
        {
            ttsbegin;
            gupPricingSimulatorInstanceValue.initValue();
            gupPricingSimulatorInstanceValue.PricingSimulatorName = _name;
            gupPricingSimulatorInstanceValue.PricingSimulatorDataAreaId = _pricingSimulatorDataAreaId;
            gupPricingSimulatorInstanceValue.insert();
            ttscommit;
        }
    }

    return gupPricingSimulatorInstanceValue;
}

public static GUPPricingSimulatorInstanceValue findByPricingSimulator(ConfigName _name, DataAreaId _pricingSimulatorDataAreaId, boolean _forupdate = false)
{
    GUPPricingSimulatorInstanceValue gupPricingSimulatorInstanceValue;

    if (_name && _pricingSimulatorDataAreaId)
    {
        gupPricingSimulatorInstanceValue.selectForUpdate(_forupdate);
        select firstonly gupPricingSimulatorInstanceValue
            where gupPricingSimulatorInstanceValue.PricingSimulatorName == _name
            && gupPricingSimulatorInstanceValue.PricingSimulatorDataAreaId == _pricingSimulatorDataAreaId;
    }

    return gupPricingSimulatorInstanceValue;
}

internal static GUPPricingSimulatorInstanceValue find(RefRecId _recId, boolean _forupdate = false)
{
    GUPPricingSimulatorInstanceValue record;

    if (_recId)
    {
        record.selectForUpdate(_forupdate);

        select firstonly record
            where record.RecId == _recId;
    }

    return record;
}
